head.b:skin:
:root{--bg:#080b14;--panel:#101522;--panel2:#151c2c;--blue:#4f7cff;--cyan:#65e5ff;--lime:#d5ff72;--white:#f6f7fb;--muted:#a1a9bb;--line:rgba(255,255,255,.12);--max:1240px}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:var(--bg);color:var(--white);font-family:'DM Sans',sans-serif;line-height:1.6;overflow-x:hidden}a{color:inherit;text-decoration:none}button{font:inherit}img,svg{max-width:100%}.container{width:min(var(--max),calc(100% - 56px));margin:auto}.display{font-family:'Space Grotesk',sans-serif;letter-spacing:-.065em}.gradient{background:linear-gradient(100deg,#fff 5%,#9cb6ff 42%,#65e5ff 80%);color:transparent;background-clip:text;-webkit-background-clip:text}.eyebrow{font-size:.72rem;font-weight:700;letter-spacing:.19em;text-transform:uppercase;color:var(--cyan);display:inline-flex;gap:10px;align-items:center}.eyebrow:before{content:'';width:24px;height:1px;background:var(--cyan)}.pill{display:inline-flex;align-items:center;gap:9px;padding:8px 12px;border:1px solid var(--line);border-radius:99px;color:#dbe2f4;font-size:.76rem;background:rgba(255,255,255,.035)}.dot{width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 12px #d5ff72}.btn{display:inline-flex;align-items:center;justify-content:center;gap:14px;padding:14px 19px;border-radius:10px;border:1px solid transparent;font-weight:700;font-size:.9rem;transition:transform .25s,background .25s,border-color .25s;cursor:pointer}.btn:hover{transform:translateY(-3px)}.btn-primary{background:var(--lime);color:#11150a;box-shadow:0 8px 35px rgba(213,255,114,.13)}.btn-primary:hover{background:#e1ff9a}.btn-ghost{border-color:var(--line);background:rgba(255,255,255,.035)}.btn-ghost:hover{border-color:rgba(101,229,255,.6)}.topline{height:3px;background:linear-gradient(90deg,var(--blue),var(--cyan),var(--lime))}
/* Intro stays progressive-enhancement safe: the actual page is visible even if JavaScript is blocked. */
.intro{position:fixed;inset:0;z-index:999;display:grid;place-items:center;padding:24px;background:radial-gradient(ellipse at 50% 35%,rgba(79,124,255,.25),transparent 40%),#080b14;transition:opacity .65s,visibility .65s}.intro.hidden{opacity:0;visibility:hidden;pointer-events:none}.intro-inner{text-align:center;max-width:680px;animation:rise .9s both}.logo-big{width:72px;height:72px;border-radius:22px;margin:0 auto 24px;display:grid;place-items:center;background:linear-gradient(145deg,#d5ff72,#65e5ff 48%,#4f7cff);color:#080b14;font:700 2.5rem 'Space Grotesk';box-shadow:0 0 80px rgba(79,124,255,.35);transform:rotate(-7deg)}.logo-big span{transform:rotate(7deg)}.intro h1{font:700 clamp(2.2rem,7vw,4.7rem)/1.02 'Space Grotesk';letter-spacing:-.075em;margin:0}.intro .founder{font-size:.75rem;letter-spacing:.3em;color:var(--cyan);margin:18px 0 3px}.intro .tagline{color:var(--muted);margin:0 0 28px}.intro-orbit{position:absolute;width:min(85vw,650px);aspect-ratio:1;border:1px solid rgba(101,229,255,.12);border-radius:50%;pointer-events:none}.intro-orbit:after{content:'';position:absolute;inset:10%;border:1px dashed rgba(79,124,255,.2);border-radius:50%;animation:spin 35s linear infinite}
.header{position:sticky;top:0;z-index:80;background:rgba(8,11,20,.82);backdrop-filter:blur(18px);border-bottom:1px solid rgba(255,255,255,.08)}.nav{height:78px;display:flex;align-items:center;justify-content:space-between;gap:22px}.brand{display:flex;align-items:center;gap:11px;font:700 1.05rem 'Space Grotesk';letter-spacing:-.035em}.brand-icon{width:37px;height:37px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(145deg,var(--lime),var(--cyan));color:#101522;font-size:1.3rem}.navlinks{display:flex;align-items:center;gap:27px;color:#c4cad8;font-size:.85rem}.navlinks a:hover{color:var(--cyan)}.navlinks .navbutton{background:var(--white);color:#0a0d15;padding:10px 15px;border-radius:9px;font-weight:700}.menu{display:none;border:1px solid var(--line);background:var(--panel);color:white;border-radius:10px;padding:9px 12px}
.hero{position:relative;padding:82px 0 68px;overflow:hidden}.hero:before{content:'';position:absolute;width:520px;height:520px;right:-210px;top:-130px;background:rgba(79,124,255,.18);filter:blur(100px);border-radius:50%;pointer-events:none}.hero:after{content:'';position:absolute;left:-170px;bottom:-250px;width:400px;height:400px;background:rgba(101,229,255,.08);filter:blur(100px);border-radius:50%;pointer-events:none}.hero-grid{position:relative;z-index:1;display:grid;grid-template-columns:.95fr 1.05fr;gap:45px;align-items:center}.hero-copy h2{font:700 clamp(3.25rem,6.5vw,6.15rem)/.98 'Space Grotesk';letter-spacing:-.085em;margin:22px 0}.hero-copy p{color:var(--muted);max-width:500px;font-size:1.03rem}.hero-actions{display:flex;flex-wrap:wrap;gap:11px;margin-top:28px}.hero-meta{display:flex;align-items:center;gap:11px;margin-top:30px;color:#b4bdce;font-size:.8rem}.hero-meta b{color:var(--lime);font-weight:600}.visual-wrap{position:relative;min-width:0;padding:17px;border:1px solid var(--line);border-radius:24px;background:linear-gradient(145deg,rgba(255,255,255,.075),rgba(255,255,255,.015));box-shadow:0 30px 90px rgba(0,0,0,.35);transform:rotate(1.1deg)}.visual-top{display:flex;justify-content:space-between;align-items:center;color:#aeb7ca;font-size:.68rem;letter-spacing:.13em;padding:2px 3px 14px}.window-dots{display:flex;gap:5px}.window-dots i{width:6px;height:6px;border-radius:50%;background:#667087}.window-dots i:first-child{background:var(--lime)}.visual-canvas{position:relative;overflow:hidden;aspect-ratio:1.05/1;border-radius:15px;background:#131a2b;isolation:isolate}.visual-canvas:before{content:'';position:absolute;inset:0;background:linear-gradient(120deg,rgba(79,124,255,.12),transparent 50%),radial-gradient(circle at 70% 30%,rgba(101,229,255,.15),transparent 35%);z-index:-1}.scene{position:absolute;inset:0;display:grid;place-items:center;opacity:0;transform:scale(.93) rotate(-2deg);transition:opacity .7s,transform .7s}.scene.active{opacity:1;transform:scale(1) rotate(0)}.scene svg{width:100%;height:100%;max-height:440px}.float-tag{position:absolute;z-index:3;padding:10px 13px;background:rgba(15,21,35,.88);border:1px solid var(--line);border-radius:12px;box-shadow:0 12px 32px #0004;font-size:.72rem;backdrop-filter:blur(10px);animation:float 5s ease-in-out infinite}.tag-one{left:-24px;top:23%}.tag-two{right:-19px;bottom:18%;animation-delay:-2s}.tag-icon{display:inline-grid;place-items:center;width:25px;height:25px;background:var(--lime);color:#101522;border-radius:7px;margin-right:7px;font-weight:900}.visual-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 3px 1px}.visual-foot strong{font:600 1rem 'Space Grotesk'}.visual-foot span{font-size:.72rem;color:var(--muted)}.scene-count{color:var(--cyan)!important;font-variant-numeric:tabular-nums}
.ticker{overflow:hidden;border-block:1px solid var(--line);background:#0c101b}.ticker-track{display:flex;align-items:center;gap:28px;width:max-content;padding:18px 0;animation:ticker 28s linear infinite}.ticker-track span{font:600 .85rem 'Space Grotesk';letter-spacing:.08em;text-transform:uppercase;color:#c4ccdd;white-space:nowrap}.ticker-track b{font-size:1rem;color:var(--lime)}
.section{padding:100px 0}.section-head{display:flex;align-items:end;justify-content:space-between;gap:30px;margin-bottom:36px}.section-head h2{font:700 clamp(2.4rem,5vw,4.3rem)/1.02 'Space Grotesk';letter-spacing:-.075em;margin:13px 0 0}.section-head p{max-width:400px;color:var(--muted);margin:0}.services{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.service{position:relative;overflow:hidden;min-height:240px;padding:23px;border:1px solid var(--line);border-radius:16px;background:linear-gradient(145deg,#141a29,#0d111c);transition:transform .3s,border-color .3s}.service:after{content:'';position:absolute;width:100px;height:100px;right:-55px;bottom:-55px;border-radius:50%;background:var(--blue);filter:blur(40px);opacity:0;transition:opacity .3s}.service:hover{transform:translateY(-7px);border-color:rgba(101,229,255,.45)}.service:hover:after{opacity:.45}.service-icon{width:46px;height:46px;display:grid;place-items:center;border:1px solid rgba(101,229,255,.2);border-radius:13px;background:rgba(79,124,255,.13);color:var(--cyan);font-size:1.35rem}.service h3{font:600 1.15rem 'Space Grotesk';margin:23px 0 8px}.service p{font-size:.85rem;color:var(--muted);margin:0}.service .number{position:absolute;right:20px;top:18px;color:#606a7e;font-size:.7rem}
.work-section{background:#0b0f19;border-block:1px solid rgba(255,255,255,.06)}.filters{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:24px}.filter{border:1px solid var(--line);border-radius:99px;padding:9px 15px;background:transparent;color:#c7cede;cursor:pointer;font-size:.8rem;transition:.2s}.filter.active,.filter:hover{background:var(--lime);border-color:var(--lime);color:#101522}.projects{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.project{overflow:hidden;border:1px solid var(--line);border-radius:17px;background:#111725;transition:transform .3s,border-color .3s}.project:hover{transform:translateY(-5px);border-color:rgba(101,229,255,.4)}.project[hidden]{display:none}.project-art{position:relative;overflow:hidden;aspect-ratio:1.5;background:#131b2c}.project-art svg{width:100%;height:100%;display:block;transition:transform .6s}.project:hover .project-art svg{transform:scale(1.04)}.project-art:after{content:'CONCEPT STUDY';position:absolute;bottom:13px;left:14px;font-size:.61rem;letter-spacing:.16em;color:#fff;background:#080b14b8;border:1px solid #ffffff25;border-radius:5px;padding:5px 8px}.project-info{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:17px 19px}.project-info h3{font:600 1.12rem 'Space Grotesk';margin:0}.project-info p{color:var(--muted);font-size:.79rem;margin:4px 0 0}.project-link{width:36px;height:36px;border:1px solid var(--line);border-radius:50%;display:grid;place-items:center;color:var(--lime)}
.feature{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center;padding:40px;border:1px solid var(--line);border-radius:22px;background:radial-gradient(ellipse at 90% 30%,rgba(79,124,255,.2),transparent 45%),#101522;overflow:hidden}.feature h2{font:700 clamp(2.5rem,5vw,4.4rem)/1 'Space Grotesk';letter-spacing:-.075em;margin:15px 0}.feature p{color:var(--muted);max-width:470px}.feature-art{position:relative;min-height:270px;display:grid;place-items:center}.orb{width:180px;aspect-ratio:1;border-radius:38%;background:linear-gradient(140deg,#d5ff72 0%,#65e5ff 32%,#4f7cff 68%,#392a79);box-shadow:inset -20px -22px 45px #080b1488,0 0 70px #4f7cff35;transform:rotate(25deg);animation:float 6s ease-in-out infinite}.orb-ring{position:absolute;width:280px;height:110px;border:1px solid rgba(101,229,255,.65);border-radius:50%;transform:rotate(-28deg);animation:spin 24s linear infinite}.orb-ring.two{width:300px;height:130px;transform:rotate(55deg);border-color:rgba(213,255,114,.5);animation-direction:reverse}
.about-grid{display:grid;grid-template-columns:.85fr 1.15fr;gap:55px;align-items:center}.about-art{min-height:360px;position:relative;display:grid;place-items:center;border:1px solid var(--line);border-radius:20px;background:radial-gradient(circle at 50% 40%,rgba(79,124,255,.25),transparent 50%),#101522;overflow:hidden}.about-art:before{content:'CREATIVE MIND / VISUAL THINKER';position:absolute;bottom:20px;left:20px;font-size:.65rem;letter-spacing:.15em;color:#8e9ab2}.monogram{font:700 clamp(7rem,15vw,12rem)/1 'Space Grotesk';letter-spacing:-.13em;color:transparent;-webkit-text-stroke:2px var(--cyan);text-shadow:10px 10px 0 rgba(79,124,255,.28);transform:rotate(-7deg)}.about-copy h2{font:700 clamp(2.6rem,5vw,4.2rem)/1.02 'Space Grotesk';letter-spacing:-.075em;margin:14px 0}.about-copy p{color:var(--muted)}.skills{display:flex;flex-wrap:wrap;gap:8px;margin:22px 0}.skills span{border:1px solid var(--line);border-radius:8px;padding:8px 11px;color:#cbd3e2;font-size:.77rem}
.contact{padding:90px 0;text-align:center;background:radial-gradient(ellipse at 50% 100%,rgba(79,124,255,.18),transparent 55%)}.contact h2{font:700 clamp(2.8rem,7vw,5.6rem)/.98 'Space Grotesk';letter-spacing:-.08em;margin:17px 0}.contact p{max-width:550px;margin:0 auto 25px;color:var(--muted)}.contact-actions{display:flex;justify-content:center;gap:11px;flex-wrap:wrap}.footer{border-top:1px solid var(--line);padding:24px 0;color:var(--muted);font-size:.78rem}.footer-inner{display:flex;align-items:center;justify-content:space-between;gap:20px}.socials{display:flex;gap:8px}.socials a{width:36px;height:36px;display:grid;place-items:center;border:1px solid var(--line);border-radius:50%;color:#cbd3e2;font-size:.75rem}.socials a:hover{border-color:var(--cyan);color:var(--cyan)}
.reveal{opacity:0;transform:translateY(22px);transition:opacity .7s ease,transform .7s ease}.reveal.visible{opacity:1;transform:translateY(0)}.blogger-hidden{display:none}
@keyframes rise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}@keyframes float{0%,100%{translate:0 0}50%{translate:0 -13px}}@keyframes spin{to{transform:rotate(360deg)}}@keyframes ticker{to{transform:translateX(-50%)}}
@media(max-width:1000px){.hero-grid{grid-template-columns:1fr;gap:38px}.hero-copy{text-align:center}.hero-copy p{margin-inline:auto}.hero-actions,.hero-meta{justify-content:center}.visual-wrap{width:min(100%,720px);margin:auto}.services{grid-template-columns:repeat(2,minmax(0,1fr))}.about-grid{gap:30px}.feature{gap:15px;padding:30px}}
@media(max-width:700px){.container{width:calc(100% - 32px)}.nav{height:68px}.menu{display:block}.navlinks{display:none;position:absolute;left:0;right:0;top:68px;padding:20px 22px 24px;background:#0e1320;border-bottom:1px solid var(--line);flex-direction:column;align-items:stretch;gap:18px}.navlinks.open{display:flex}.navlinks .navbutton{text-align:center}.hero{padding:54px 0 45px}.hero-grid{gap:30px}.hero-copy h2{font-size:clamp(3.05rem,12vw,4.6rem)}.hero-copy p{font-size:.95rem}.visual-wrap{padding:10px;border-radius:18px}.visual-canvas{aspect-ratio:.96/1}.float-tag{font-size:.65rem;padding:8px}.tag-one{left:-7px}.tag-two{right:-6px}.section{padding:68px 0}.section-head{display:block;margin-bottom:25px}.section-head p{margin-top:13px}.services{gap:10px}.service{padding:16px;min-height:215px}.service h3{font-size:1rem}.service p{font-size:.8rem}.projects{grid-template-columns:1fr;gap:14px}.project-info{padding:15px}.feature{grid-template-columns:1fr;padding:27px 22px;gap:4px}.feature-art{min-height:220px;grid-row:1}.orb{width:135px}.orb-ring{width:220px;height:90px}.about-grid{grid-template-columns:1fr;gap:25px}.about-art{min-height:260px}.monogram{font-size:8rem}.contact{padding:68px 0}.footer-inner{flex-direction:column;text-align:center}.socials{justify-content:center}}
@media(max-width:390px){.container{width:calc(100% - 24px)}.brand{font-size:.92rem}.brand-icon{width:33px;height:33px}.hero-copy h2{font-size:2.8rem}.hero-actions .btn{width:100%}.services{grid-template-columns:1fr}.service{min-height:0}.visual-foot{align-items:flex-start;flex-direction:column;gap:3px}.intro h1{font-size:2.25rem}.intro .btn{width:100%}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}.reveal{opacity:1;transform:none}}

body.script:
//
(function(){
var intro=document.getElementById('introScreen'),enter=document.getElementById('enterStudio');
function dismissIntro(){if(intro)intro.classList.add('hidden');try{sessionStorage.setItem('scs-intro-seen','1')}catch(e){}}
try{if(sessionStorage.getItem('scs-intro-seen')==='1'&&intro)intro.classList.add('hidden')}catch(e){}
if(enter)enter.addEventListener('click',dismissIntro);
var nav=document.getElementById('navLinks'),menu=document.getElementById('menuToggle');
if(menu&&nav){menu.addEventListener('click',function(){var open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open?'true':'false')});nav.querySelectorAll('a').forEach(function(a){a.addEventListener('click',function(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')})})}
var scenes=[].slice.call(document.querySelectorAll('.scene')),sceneTitle=document.getElementById('sceneTitle'),sceneSub=document.getElementById('sceneSub'),sceneCount=document.getElementById('sceneCount'),names=[['Shape the Future','Graphic direction · 01 / 04'],['North Studio','Brand identity · 02 / 04'],['Motion in Color','Motion graphics · 03 / 04'],['Sculpted Light','3D exploration · 04 / 04']],idx=0,timer=null,paused=false,reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function showScene(n){if(!scenes.length)return;idx=(n+scenes.length)%scenes.length;scenes.forEach(function(s,i){s.classList.toggle('active',i===idx)});if(sceneTitle)sceneTitle.textContent=names[idx][0];if(sceneSub)sceneSub.textContent=names[idx][1];if(sceneCount)sceneCount.textContent=('0'+(idx+1)).slice(-2)+' — 0'+scenes.length}
function start(){stop();if(!paused&&!reduced&&!document.hidden)timer=setInterval(function(){showScene(idx+1)},3600)}function stop(){if(timer){clearInterval(timer);timer=null}}
showScene(0);start();var canvas=document.getElementById('visualCanvas');if(canvas){canvas.addEventListener('mouseenter',stop);canvas.addEventListener('mouseleave',start);var sx=0;canvas.addEventListener('touchstart',function(e){if(e.touches.length)sx=e.touches[0].clientX},{passive:true});canvas.addEventListener('touchend',function(e){if(e.changedTouches.length&&Math.abs(e.changedTouches[0].clientX-sx)>40){showScene(idx+(e.changedTouches[0].clientX<sx?1:-1));start()}},{passive:true})}
document.addEventListener('visibilitychange',function(){if(document.hidden)stop();else start()});
document.querySelectorAll('.filter').forEach(function(btn){btn.addEventListener('click',function(){var f=btn.getAttribute('data-filter');document.querySelectorAll('.filter').forEach(function(b){b.classList.toggle('active',b===btn)});document.querySelectorAll('.project').forEach(function(card){var tags=(card.getAttribute('data-tags')||'').split(' ');card.hidden=!(f==='all'||tags.indexOf(f)!==-1)})})});
if('IntersectionObserver'in window){var io=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}})},{threshold:.1});document.querySelectorAll('.reveal').forEach(function(el){io.observe(el)})}else{document.querySelectorAll('.reveal').forEach(function(el){el.classList.add('visible')})}
if(reduced)document.querySelectorAll('.reveal').forEach(function(el){el.classList.add('visible')});
var year=document.getElementById('yearNow');if(year)year.textContent=new Date().getFullYear();
})();
//
